#!/usr/bin/env python3
"""Read-only byte projection. Never imports a builder or emits kernel evidence."""
from pathlib import Path
import hashlib
import json
import sys

B = Path('/dev/shm/rc-lean-g7-survival-integration-20261010T223510.923050Z')
R = B / '.build/runs/20261010T223805.816906Z'
WN = Path('/dev/shm/rc-lean-g6-natural-common-20261011T013832.645024Z')
PINS = {
    str(B/'DEPENDENCY-GRAPH.json'): 'e05a87db2b34f42aada87a958f7ff9114c68a817458b5919f7ecac62386fbacd',
    str(B/'CACHE-INSTALL-ALIASES.json'): '739145972c6fdf14c641c5e72e7a22f62572408a56fb825c4278127c00c6cb80',
    str(R/'targets/current_connected/ACTUAL-IMPORTED-ARTIFACTS.json'): 'f9ba81430223f778c447a3b9287ab947fbb7c4c80ebd10a0af5daa88a4643172',
}
GUARDS = {'Mathlib.Analysis.Convex.Caratheodory', 'Mathlib.Data.FinEnum',
          'Mathlib.Algebra.MvPolynomial.Polynomial', 'Mathlib.Algebra.MvPolynomial.Funext'}
NEW = {'G4LiteralLastChildExitCut': ['G1OriginalCalendarDecomposition',
       'G1SeparatedAgendaSupportCuts', 'G1OriginalExitBatchBinding'],
       'G4PartialExitSeparation': ['G4LiteralLastChildExitCut']}
SUFFIXES = ['.olean', '.olean.private', '.olean.server', '.ilean', '.ir']
NEW_CONTEXT = ('/dev/shm/rc-lean-g4-conditional-cut-20261011T000000.000000Z/'
               '.build/runs/20261011T000000.000000Z/targets/'
               'extraction_g4-partial-exit-separation/objects')


def sha(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as f:
        for data in iter(lambda: f.read(1048576), b''):
            h.update(data)
    return h.hexdigest()


def main():
    for p, expected in PINS.items():
        assert sha(p) == expected, p
    graph = json.loads((B/'DEPENDENCY-GRAPH.json').read_bytes())['targets']['current/connected']
    g, selected = graph['modules'], set()
    def add(m):
        if m in selected:
            return
        selected.add(m)
        for i in g[m]['imports']:
            if i in g:
                add(i)
    for m in NEW['G4LiteralLastChildExitCut']:
        add(m)
    assert len(selected) == 239 and not selected & GUARDS
    aliases = {e['module']: e for e in json.loads((B/'CACHE-INSTALL-ALIASES.json').read_bytes())['entries']}
    records = json.loads((R/'targets/current_connected/ACTUAL-IMPORTED-ARTIFACTS.json').read_bytes())
    bundles, rows = {}, {}
    for row in records:
        bundles.setdefault(row['module'], {})[row['suffix']] = row['sha256']
        rows.setdefault(row['module'], []).append(row)
    old_context = str(R/'targets/current_connected/objects')
    # All standard transitive imports are within the accepted parent union.
    # Adding unused protected guards makes this a conservative superset.
    all_names = (set(bundles)-set(g)) | selected | GUARDS | set(NEW)
    def entry(m):
        out = NEW_CONTEXT+'/'+m.replace('.', '/')+'.olean'
        if m in selected | GUARDS:
            artifacts, resolved = aliases[m]['object_artifacts'], out
        elif m in NEW:
            artifacts, resolved = {s: 'f'*64 for s in SUFFIXES}, out
        else:
            artifacts = bundles[m]
            p = next(r['path'] for r in rows[m] if r['suffix'] == '.olean')
            resolved = str(Path(p).resolve(strict=True))
            out = p.replace(old_context, NEW_CONTEXT) if p.startswith(old_context+'/') else p
        return {'lean_path': out, 'resolved_target': resolved, 'artifacts': artifacts}
    def namespace_bytes(imports):
        row = {'context': NEW_CONTEXT, 'imports': {m: entry(m) for m in imports}}
        return len((json.dumps(row, sort_keys=True)+'\n').encode())
    parts = {
        'warm_component_dependency_calls': sum(namespace_bytes(g[m]['imports']) for m in selected),
        'conservative_extra_guard_dependency_calls': sum(namespace_bytes(g[m]['imports']) for m in GUARDS),
        'fresh_component_precheck_and_before_after_calls': 3*sum(namespace_bytes(x) for x in NEW.values()),
        'aggregate_audit_before_after_calls': 2*namespace_bytes(['G4PartialExitSeparation'])+
            2*namespace_bytes(['G4PartialExitSeparation', 'Lean.Util.CollectAxioms']),
        'all_imported_superset_calls': sum(namespace_bytes([m]) for m in all_names),
    }
    model = []
    for m in sorted(all_names):
        if m in NEW:
            for suffix in SUFFIXES:
                model.append({'module': m, 'suffix': suffix,
                              'path': NEW_CONTEXT+'/'+m.replace('.', '/')+suffix,
                              'bytes': 2097152, 'sha256': 'f'*64})
        else:
            for row in rows[m]:
                p = row['path']
                model.append({**row, 'path': p.replace(old_context, NEW_CONTEXT)
                              if p.startswith(old_context+'/') else p})
    cached = []
    for m in sorted(selected):
        row = aliases[m]
        assert sha(row['staged_receipt']) == row['receipt_sha256']
        cached.append(json.loads(Path(row['staged_receipt']).read_bytes()))
    receipt_array = len(json.dumps(cached, indent=2).encode())
    ledger = len((json.dumps(model, indent=2)+'\n').encode())
    namespace = sum(parts.values())
    # Extra nesting and four bounded future receipt records are separate,
    # disclosed allowances; their actual serialization must be checked.
    fresh_receipts, nesting = 4*65536, 200000
    total = namespace+ledger+receipt_array+fresh_receipts+nesting
    print(json.dumps({
        'status': 'SOURCE_ONLY_BYTE_PROJECTION_NOT_KERNEL_OR_ARTIFACT_EVIDENCE',
        'producer_sha256': sha(__file__), 'inputs': PINS,
        'selected239_order': [m for m in graph['order'] if m in selected],
        'staging_only_guards': sorted(GUARDS), 'executed_modules': 241,
        'staging_modules': 245, 'warm_staging_modules': 243, 'fresh_modules': 2,
        'source_plan_selected_tuple_digest': hashlib.sha256(json.dumps(
            [[m, g[m]['sha256'], g[m]['imports']] for m in sorted(selected | GUARDS)],
            separators=(',', ':')).encode()).hexdigest(),
        'imported_superset_modules': len(all_names), 'artifact_rows': len(model),
        'context_template': NEW_CONTEXT, 'context_utf8_bytes': len(NEW_CONTEXT),
        'namespace_projected_upper_bytes': namespace, 'namespace_parts': parts,
        'artifact_ledger_projected_upper_bytes': ledger,
        'exact239_receipt_array_bytes': receipt_array,
        'four_fresh_receipt_allowance_bytes': fresh_receipts,
        'nested_result_format_allowance_bytes': nesting,
        'namespace_ledger_result_projected_upper_bytes': total,
        'remaining_in_metadata20MiB_bytes': 20*1048576-total,
        'conditions': [
            'Fixed future context prefix length and ASCII logical module names; longer paths require remeasurement.',
            'No additional imports, new roots or source changes; actual all-imported set must be within the parent transitive superset plus two new logical modules.',
            'Fresh file bytes must satisfy the separately monitored2MiB combined-bundle ceiling; all five suffixes are included in the model.',
            'Actual new receipts must each fit64KiB; otherwise stop and retain the full failed outcome.',
            'Remaining20MiB covers full stdout, other normal run/namespace/native/cache-transport/guard records; it is not permission to omit any record.',
            'Actual plain audit, objects and complete export are not produced or predicted by this calculation.'
